import { useState } from "react";
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from "recharts";
import { Cloud, CloudRain, CloudSnow, CloudLightning, RotateCcw } from "lucide-react";

// 颜色用采云色号：星光橙、云底蓝、暖木棕、印章红
const KINDS = [
  { id: "cumulus", name: "积云", Icon: Cloud, color: "#FFA92E" },
  { id: "rain", name: "雨云", Icon: CloudRain, color: "#7E5EFF" },
  { id: "snow", name: "雪云", Icon: CloudSnow, color: "#AE8B7F" },
  { id: "storm", name: "雷云", Icon: CloudLightning, color: "#A52525" },
];
const EMPTY = { cumulus: 0, rain: 0, snow: 0, storm: 0 };

export default function CloudCounter() {
  const [counts, setCounts] = useState({ cumulus: 3, rain: 1, snow: 0, storm: 2 });
  const data = KINDS.map((k) => ({ name: k.name, value: counts[k.id], color: k.color }));
  const total = data.reduce((sum, d) => sum + d.value, 0);

  return (
    <div
      className="min-h-screen flex items-center justify-center p-6"
      style={{ background: "linear-gradient(170deg, #F3E8DC, #E8D6C4 55%, #D6BCAB)", color: "#2D2D2D" }}
    >
      <div className="w-full max-w-md rounded-2xl p-6 shadow-xl" style={{ background: "rgba(255, 248, 240, 0.8)" }}>
        <h1 className="text-2xl font-bold" style={{ color: "#A52525" }}>采云计数</h1>
        <p className="mt-1 text-sm" style={{ color: "#5F4943" }}>点一朵，采一朵。今天一共采了 {total} 朵。</p>

        <div className="grid grid-cols-4 gap-2 mt-5">
          {KINDS.map(({ id, name, Icon, color }) => (
            <button
              key={id}
              type="button"
              onClick={() => setCounts((c) => ({ ...c, [id]: c[id] + 1 }))}
              className="flex flex-col items-center gap-1 rounded-xl py-3 text-sm font-bold bg-white shadow"
            >
              <Icon size={28} color={color} />
              {name}
            </button>
          ))}
        </div>

        <div className="h-48 mt-6">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={data} margin={{ top: 4, right: 4, left: -16, bottom: 0 }}>
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: "#2D2D2D", fontSize: 12 }} />
              <YAxis allowDecimals={false} axisLine={false} tickLine={false} tick={{ fill: "#6D6D6D", fontSize: 12 }} />
              <Tooltip cursor={{ fill: "rgba(165, 37, 37, 0.06)" }} formatter={(v) => [v + " 朵", "采了"]} />
              <Bar dataKey="value" radius={[6, 6, 0, 0]}>
                {data.map((d) => (
                  <Cell key={d.name} fill={d.color} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>

        <button
          type="button"
          onClick={() => setCounts(EMPTY)}
          className="mt-4 flex items-center gap-1 text-sm font-bold"
          style={{ color: "#6D6D6D" }}
        >
          <RotateCcw size={14} /> 清空
        </button>
      </div>
    </div>
  );
}

